        internal Task MatchesTask;DateTime lastMatchRefresh;long matchingTotal;const int PageSize=1000;
        void InitializeAnalyzerExtensions(StackPanel header,Panel actions){
            FilterCategory.Items.Add(L.Text("analyzer.allCategories"));foreach(string key in DiskScanOptions.CategoryKeys)FilterCategory.Items.Add(L.Text("analyzer.category."+key));FilterCategory.SelectedIndex=0;
            var filters=new WrapPanel();filters.Children.Add(Field("analyzer.filterCategory",FilterCategory));filters.Children.Add(Field("analyzer.minimumMiB",new NumberSpinner(FilterSize,0,1000000000)));filters.Children.Add(Field("analyzer.minimumDays",new NumberSpinner(FilterAge,0,100000)));filters.Children.Add(Field("analyzer.masks",FilterMasks));filterPanel.Children.Add(filters);
            var exclusions=new DockPanel();exclusions.Children.Add(Field("analyzer.excludeFolders",FilterExclusions));var apply=CopyUi.Button(L.Text("analyzer.applyFilters"),delegate{if(cancellation==null)ScanTask=Scan();});DockPanel.SetDock(apply,Dock.Right);exclusions.Children.Insert(0,apply);filterPanel.Children.Add(exclusions);
            filterPanel.Children.Add(new TextBlock{Text=L.Text("analyzer.filtersHelp"),TextWrapping=TextWrapping.Wrap,Foreground=FluentTheme.Muted,Margin=new Thickness(4,3,4,6)});
            header.Children.Add(new Expander{Header=L.Text("analyzer.filters"),Content=filterPanel,Margin=new Thickness(0,0,0,8)});
            var filesBody=new DockPanel();var fileActions=new WrapPanel();DockPanel.SetDock(fileActions,Dock.Bottom);filesBody.Children.Add(fileActions);
            fileActions.Children.Add(CopyUi.Button("◀",delegate{if(matchPage>0){matchPage--;MatchesTask=LoadMatches();}}));fileActions.Children.Add(CopyUi.Button("▶",delegate{if((long)(matchPage+1)*PageSize<matchingTotal){matchPage++;MatchesTask=LoadMatches();}}));
            fileActions.Children.Add(CopyUi.Button(L.Text("analyzer.allFiles"),delegate{matchKeys=null;matchLabel=L.Text("analyzer.allFiles");matchPage=0;MatchesTask=LoadMatches();}));fileActions.Children.Add(matchingStatus);filesBody.Children.Add(MatchingFiles);
            AddColumn(MatchingFiles,L.Text("analyzer.path"),"RelativePath",1);AddColumn(MatchingFiles,L.Text("analyzer.bytes"),"Size",.3);AddColumn(MatchingFiles,L.Text("analyzer.modified"),"Modified",.45);AddColumn(MatchingFiles,L.Text("analyzer.category"),"Category",.4);
            MatchingFiles.MouseDoubleClick+=delegate{var file=MatchingFiles.SelectedItem as DiskLargeFile;if(file!=null&&navigate!=null)navigate(System.IO.Path.GetDirectoryName(file.Path));};
            tabs.Items.Add(new TabItem{Header=L.Text("analyzer.matchingFiles"),Content=filesBody});
            AddColumn(Comparison,L.Text("analyzer.path"),"Path",1);AddColumn(Comparison,L.Text("analyzer.before"),"Before",.4);AddColumn(Comparison,L.Text("analyzer.after"),"After",.4);AddColumn(Comparison,L.Text("analyzer.change"),"Change",.4);Comparison.Columns[1].SortMemberPath="BeforeBytes";Comparison.Columns[2].SortMemberPath="AfterBytes";Comparison.Columns[3].SortMemberPath="Delta";
            tabs.Items.Add(new TabItem{Header=L.Text("analyzer.comparison"),Content=Comparison});
            foreach(var pair in new[]{Tuple.Create("analyzer.export",(Action)Export),Tuple.Create("analyzer.saveSnapshot",(Action)SaveSnapshot),Tuple.Create("analyzer.compareSnapshot",(Action)CompareSnapshot),Tuple.Create("duplicates.title",(Action)delegate{if(Result!=null)new DuplicateWindow(this,(selected??Result.Root).Path).Show();})}){var button=CopyUi.Button(L.Text(pair.Item1),pair.Item2);completeActions.Add(button);actions.Children.Insert(Math.Max(0,actions.Children.Count-1),button);}
            var old=actions as StackPanel;if(old!=null){old.Orientation=Orientation.Vertical;old.HorizontalAlignment=HorizontalAlignment.Stretch;var wrap=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right};foreach(UIElement child in old.Children.Cast<UIElement>().ToArray()){old.Children.Remove(child);wrap.Children.Add(child);}old.Children.Add(wrap);}
            tabs.SelectionChanged+=delegate(object sender,SelectionChangedEventArgs e){if(e.OriginalSource==tabs&&tabs.SelectedIndex==3&&MatchingFiles.ItemsSource==null&&queryCancellation==null)MatchesTask=LoadMatches();}; Chart.SliceClicked+=SelectChartRow;legend.MouseDoubleClick+=delegate{SelectChartRow(legend.SelectedItem as DiskChartRow);};
            liveTimer.Tick+=delegate{var snapshot=Interlocked.Exchange(ref pendingSnapshot,null);if(snapshot!=null&&!closed&&cancellation!=null)Present(snapshot);};liveTimer.Start();SetCompleteActions(false);
