        static StackPanel Field(string key,UIElement control){var panel=new StackPanel{Margin=new Thickness(4,2,8,2)};panel.Children.Add(new TextBlock{Text=L.Text(key),Margin=new Thickness(0,0,0,3)});panel.Children.Add(control);return panel;}
        DiskScanOptions ReadOptions(){double days;decimal mib;if(!Decimal.TryParse(FilterSize.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out mib)||mib<0||mib>1000000000||!Double.TryParse(FilterAge.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out days)||Double.IsNaN(days)||Double.IsInfinity(days)||days<0||days>100000)throw new InvalidOperationException(L.Text("analyzer.invalidFilters"));return new DiskScanOptions{StoreIndex=true,MinimumBytes=(long)(mib*1048576m),MinimumAgeDays=days,Category=FilterCategory.SelectedIndex<=0?"":DiskScanOptions.CategoryKeys[FilterCategory.SelectedIndex-1],Masks=FilterMasks.Text,Exclusions=FilterExclusions.Text};}
        void SetCompleteActions(bool enabled){foreach(var button in completeActions)button.IsEnabled=enabled;}
        internal async Task Scan(){
            if(cancellation!=null)return;DiskScanOptions options;try{options=ReadOptions();}catch(Exception ex){status.Text=ex.Message;return;}
            queryVersion++;if(queryCancellation!=null){var oldQuery=queryCancellation;queryCancellation=null;oldQuery.Cancel();}lastMatchRefresh=DateTime.MinValue;matchLabel=L.Text("analyzer.allFiles");DiskFileIndex.Delete(Result==null?null:Result.IndexPath);Result=null;matchKeys=null;matchPage=0;MatchingFiles.ItemsSource=null;Comparison.ItemsSource=null;
            cancellation=new CancellationTokenSource();var token=cancellation.Token;refresh.IsEnabled=false;stop.IsEnabled=true;filterPanel.IsEnabled=false;SetCompleteActions(false);progress.Visibility=Visibility.Visible;status.Text=L.Text("analyzer.scanning");Folders.Items.Clear();largest.ItemsSource=null;issues.ItemsSource=null;selected=null;UpdateChart();
            try{var result=await Task.Run(()=>DiskAnalysis.Scan(path,token,null,null,options,snapshot=>Interlocked.Exchange(ref pendingSnapshot,snapshot)));Interlocked.Exchange(ref pendingSnapshot,null);if(closed){DiskFileIndex.Delete(result.IndexPath);return;}Present(result);SetCompleteActions(!result.Cancelled);}
            catch(Exception ex){Interlocked.Exchange(ref pendingSnapshot,null);if(!closed)status.Text=L.Text("analyzer.failed")+": "+ex.Message;}
            finally{cancellation.Dispose();cancellation=null;if(!closed){refresh.IsEnabled=true;stop.IsEnabled=false;filterPanel.IsEnabled=true;progress.Visibility=Visibility.Collapsed;}}
        }
        void Present(DiskAnalysis result){
            Result=result;selected=result.Root;rebuildingTree=true;Folders.Items.Clear();var root=FolderItem(result.Root);Folders.Items.Add(root);root.IsExpanded=true;root.IsSelected=true;rebuildingTree=false;
            largest.ItemsSource=result.Largest.ToArray();issues.ItemsSource=result.Issues.ToArray();status.Text=L.Text(result.IsPartial?(result.Cancelled?"analyzer.partial":"analyzer.live"):"analyzer.complete")+" · "+result.Root.Size+" · "+result.Root.Files.ToString("N0")+" "+L.Text("analyzer.files")+" · "+result.Folders.ToString("N0")+" "+L.Text("analyzer.folders")+" · "+L.Text("analyzer.skipped")+": "+result.Skipped.ToString("N0");UpdateChart();
            if(tabs.SelectedIndex==3&&queryCancellation==null&&(!result.IsPartial||(DateTime.UtcNow-lastMatchRefresh).TotalSeconds>=2))MatchesTask=LoadMatches();
        }
        internal void UpdateChart(){
            if(Result==null){Chart.Rows=new List<DiskChartRow>();Chart.InvalidateVisual();legend.ItemsSource=null;return;}
            IEnumerable<DiskBucket> buckets;int group=GroupChoice.SelectedIndex;
            if(group==0){var folder=selected??Result.Root;scope.Text=folder.Path;var list=folder.Children.Select(x=>new DiskBucket{Name=System.IO.Path.GetFileName(x.Path),Key="folder:"+System.IO.Path.GetFileName(x.Path),Bytes=x.Bytes,Files=x.Files}).ToList();list.Add(new DiskBucket{Name="__direct",Key="__direct",Bytes=folder.DirectBytes,Files=folder.DirectFiles});buckets=list;}
            else{scope.Text=Result.Root.Path;buckets=group==1?(IEnumerable<DiskBucket>)Result.Extensions.Values:group==2?Result.Ages:group==3?Result.Sizes:(IEnumerable<DiskBucket>)Result.Categories.Values;}
            bool count=MetricChoice.SelectedIndex==1;var all=buckets.Select(x=>new DiskChartRow{Key=x.Key??x.Name,Keys=new HashSet<string>(new[]{x.Key??x.Name},StringComparer.OrdinalIgnoreCase),Name=group==0?(x.Key=="__direct"?L.Text("analyzer.directFiles"):x.Name):x.Name.StartsWith("analyzer.",StringComparison.Ordinal)?L.Text(x.Name):x.Name,Bytes=x.Bytes,Files=x.Files,Value=count?x.Files:x.Bytes}).Where(x=>x.Value>0).ToList();double total=all.Sum(x=>x.Value);
            if(group<2||group==4)all=all.OrderByDescending(x=>x.Value).ToList();var rows=all.Take(9).ToList();if(all.Count>9){var tail=all.Skip(9).ToArray();rows.Add(new DiskChartRow{Key="__other",Keys=new HashSet<string>(tail.Select(x=>x.Key),StringComparer.OrdinalIgnoreCase),Name=L.Text("analyzer.other"),Bytes=tail.Sum(x=>x.Bytes),Files=tail.Sum(x=>x.Files),Value=tail.Sum(x=>x.Value)});}
            if(group<2||group==4){var tiny=rows.Where(x=>x.Value/Math.Max(1,total)<.01||x.Key=="__other").ToArray();if(tiny.Length>1){rows=rows.Except(tiny).ToList();rows.Add(new DiskChartRow{Key="__other",Keys=new HashSet<string>(tiny.SelectMany(x=>x.Keys),StringComparer.OrdinalIgnoreCase),Name=L.Text("analyzer.other"),Bytes=tiny.Sum(x=>x.Bytes),Files=tiny.Sum(x=>x.Files),Value=tiny.Sum(x=>x.Value)});}}
            var colors=new Dictionary<string,System.Windows.Media.Brush>();var usedColors=new HashSet<int>();foreach(var row in rows.Where(x=>x.Key!="__other").OrderBy(x=>x.Key,StringComparer.OrdinalIgnoreCase)){int color=DiskChart.ColorIndex(row.Key);while(usedColors.Contains(color))color=(color+1)%9;usedColors.Add(color);colors[row.Key]=CompactTheme.ColorBrush(DiskChart.Colors[color]);} for(int i=0;i<rows.Count;i++){rows[i].Color=rows[i].Key=="__other"?CompactTheme.ColorBrush("#8D8999"):colors[rows[i].Key];rows[i].Share=(rows[i].Value/Math.Max(1,total)*100).ToString("N1")+" %";}
            Chart.Rows=rows;Chart.Pie=ChartChoice.SelectedIndex==0;Chart.CenterText=count?total.ToString("N0"):DiskAnalysis.FormatSize((long)total);Chart.Subtitle=L.Text(Result.IsPartial?"analyzer.liveShort":count?"analyzer.files":"analyzer.bytes");Chart.InvalidateVisual();legend.ItemsSource=rows;
        }
        internal void SelectChartRow(DiskChartRow row){if(row==null||Result==null||Result.IndexPath==null)return;matchLabel=row.Name;matchGroup=GroupChoice.SelectedIndex;matchFolder=(matchGroup==0?(selected??Result.Root):Result.Root).Path;matchKeys=new HashSet<string>(row.Keys,StringComparer.OrdinalIgnoreCase);matchPage=0;tabs.SelectedIndex=3;MatchesTask=LoadMatches();}
        async Task LoadMatches(){
            if(Result==null||Result.IndexPath==null)return;lastMatchRefresh=DateTime.UtcNow;int request=++queryVersion;if(queryCancellation!=null)queryCancellation.Cancel();var source=queryCancellation=new CancellationTokenSource();var result=Result;var keys=matchKeys==null?null:new HashSet<string>(matchKeys,StringComparer.OrdinalIgnoreCase);int group=matchGroup,page=matchPage;string folder=matchFolder;matchingStatus.Text=L.Text("analyzer.loadingFiles");
            try{long total=0;var rows=await Task.Run(()=>DiskFileIndex.Page(result.IndexPath,file=>keys==null||keys.Contains(DiskFileIndex.Bucket(file,group,folder,result.ScannedUtc)),page,PageSize,source.Token,out total));if(closed||request!=queryVersion)return;matchingTotal=total;foreach(var file in rows)file.RootPath=result.Root.Path;MatchingFiles.ItemsSource=rows;matchingStatus.Text=(matchLabel??L.Text("analyzer.allFiles"))+" · "+L.Format("analyzer.pageSummary",page+1,Math.Max(1,(total+PageSize-1)/PageSize),total)+(result.IsPartial?" · "+L.Text("analyzer.liveShort"):"");}
